from collections import deque

def comps(grid, diagonal=False):
    H,W=len(grid),len(grid[0]); seen=set(); result=[]
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    if diagonal: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
    for i in range(H):
        for j in range(W):
            if grid[i][j]==7 or (i,j) in seen: continue
            q=[(i,j)]; seen.add((i,j)); cells=[]
            while q:
                r,c=q.pop(); cells.append((r,c))
                for dr,dc in dirs:
                    nr,nc=r+dr,c+dc
                    if 0<=nr<H and 0<=nc<W and grid[nr][nc]!=7 and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            vals=sorted(set(grid[r][c] for r,c in cells if grid[r][c] not in (0,7)))
            result.append((min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells),len(cells),vals))
    return sorted(result)
comps(rows)
